/**
 * @rouar/sdk/db のアダプタと、サーバーエントリの自己停止をつなぐ。
 * 両者が別々のモジュールとして読み込まれても同じ値を見るように、globalThis に置く。
 */
const PROBE_KEY = Symbol.for("rouar.sdk.unsettledSubmissionsProbe");

export type UnsettledSubmissionsProbe = () => Promise<boolean>;

type ProbeHolder = { [PROBE_KEY]?: UnsettledSubmissionsProbe };

export function setUnsettledSubmissionsProbe(
	probe: UnsettledSubmissionsProbe | undefined,
): void {
	(globalThis as ProbeHolder)[PROBE_KEY] = probe;
}

export function getUnsettledSubmissionsProbe():
	| UnsettledSubmissionsProbe
	| undefined {
	return (globalThis as ProbeHolder)[PROBE_KEY];
}
